const godotTemplate = {
  "README.md": "# Dialogue Playground â€” Godot 4\r\n\r\nThe downloadable apple-quest demo: talk to Mira, close the conversation, touch\r\nthe red apple with green leaves, then return to Mira. Pickup removes the apple\r\nand sets numeric `hasApple = 1`; Mira's root conditions select the request at\r\n`hasApple = 0` and the thank-you at `hasApple = 1`. Returning before pickup still\r\nshows the request. Restart Play/Preview to reset. The pickup is enabled only\r\nwhen the source demo's `demoAppleQuest` flag is true.\r\n\r\nExtract this ZIP, import project.godot in Godot 4.5 or newer, and press F6\r\n(current scene) or F5 (project). No plugins, .NET, or external assets are required.\r\n\r\nMove the blue player with arrows or WASD and touch a colored NPC to talk.\r\nClick choices or use Tab and Enter. Escape closes dialogue and the variable\r\npanel. Move away and return to the NPC to restart the conversation.\r\n\r\nEvery character tree has its own NPC scene instance, even if names are identical.\r\nThe world grows vertically for larger casts, and the player's camera follows.\r\nEmpty trees show a message instead of failing. Newlines advance as dialogue pages;\r\nlong pages and lists of answers scroll in the dialogue panel.\r\n\r\nUse Test variables to change conditions. Numeric variables start at 0 and strings\r\nstart empty. All conditions on an edge must pass. Normal nodes select the first\r\navailable outgoing edge; Next is used only when there are no outgoing edges.\r\nFight nodes offer simulated win/loss choices, not a combat system.\r\n\r\nEdit scenes/main.tscn to reposition characters, scenes/player.tscn and\r\nscenes/npc.tscn to customize their shapes, and scenes/dialogue_ui.tscn for the UI.\r\nNPCs use Area2D.body_entered to detect the CharacterBody2D player. Movement pauses\r\nwhile a conversation or test panel is open. The areas are contact triggers;\r\nthey do not act as solid obstacles.\r\n\r\nDialogue is in dialogue.json: replace it with the ordinary JSON export and restart the game. Preserve your .tscn scenes, scripts, sprites and themes. NPC character_id is the stable Dialogue Maker ID; character_index is resolved at runtime so reordering characters is safe.\r\nExport again after adding or removing characters. To integrate with your game,\r\nset DialogueUI.variables, replace the test panel with your own game state,\r\nand use dialogue_session.gd for traversal. The exporter preserves original\r\nnames and text in JSON rather than treating them as scene names or script code.\r\n\r\nDialogue shortcuts: press 1–9 (top row or numeric keypad) to select the corresponding numbered option. Press 1 to continue a line or finish a conversation. Numbers appear separately from dialogue text; locked options cannot be selected. Shortcuts pause while Test variables is open. Options above 9 remain clickable.\r\n\r\nWaiting conditions: waitUntilMet defaults to true. Blocked waiting connections remember their upstream node per character for the current game runtime. On returning, the same node is displayed until its condition passes, then the connection is followed. Questions and fights still require a choice. Uncheck this setting to restart normally. This progress is in memory; add your own save-game integration for persistence across reloads.\r\n\r\n## Updating an existing integration\r\n\r\nExport once to bootstrap the engine project. Afterwards export ordinary JSON and replace only `dialogue.json`. Keep character/node IDs stable. Updates take effect at the next run, not mid-conversation; game saves need their own migration policy if nodes are deleted. Variable dictionaries remain game-owned while running; setting a condition never changes a variable automatically. New condition variables need wiring to your gameplay.\r\n\r\nOlder exports require a one-time integration upgrade. Merge scripts/main.gd, scripts/npc.gd and scripts/dialogue_ui.gd, then set each existing NPC character_id to its original Dialogue Maker ID. Keep your scenes and themes. Custom interactions can call open_character_id. When packaging, include *.json in the export preset non-resource file filter.\r\n",
  "scenes/dialogue_ui.tscn": "[gd_scene load_steps=2 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/dialogue_ui.gd\" id=\"1\"]\n\n[node name=\"DialogueUI\" type=\"CanvasLayer\"]\nscript = ExtResource(\"1\")\n\n[node name=\"HUD\" type=\"MarginContainer\" parent=\".\"]\nanchor_right = 1.0\noffset_left = 16.0\noffset_top = 16.0\noffset_right = -16.0\noffset_bottom = 76.0\n\n[node name=\"Row\" type=\"HBoxContainer\" parent=\"HUD\"]\nlayout_mode = 2\ntheme_override_constants/separation = 16\n\n[node name=\"Instructions\" type=\"Label\" parent=\"HUD/Row\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntext = \"Move: arrows / WASD | Touch an NPC to talk\\nEnter / click: choose | Esc: close | Blue square = you\"\nautowrap_mode = 3\n\n[node name=\"Variables\" type=\"Button\" parent=\"HUD/Row\"]\nlayout_mode = 2\ntext = \"Test variables\"\n\n[node name=\"DialoguePanel\" type=\"PanelContainer\" parent=\".\"]\nvisible = false\nanchor_top = 1.0\nanchor_right = 1.0\nanchor_bottom = 1.0\noffset_left = 24.0\noffset_top = -320.0\noffset_right = -24.0\noffset_bottom = -24.0\ngrow_horizontal = 2\ngrow_vertical = 0\n\n[node name=\"Margin\" type=\"MarginContainer\" parent=\"DialoguePanel\"]\nlayout_mode = 2\ntheme_override_constants/margin_left = 20\ntheme_override_constants/margin_top = 16\ntheme_override_constants/margin_right = 20\ntheme_override_constants/margin_bottom = 16\n\n[node name=\"Scroll\" type=\"ScrollContainer\" parent=\"DialoguePanel/Margin\"]\nlayout_mode = 2\nhorizontal_scroll_mode = 0\n\n[node name=\"Content\" type=\"VBoxContainer\" parent=\"DialoguePanel/Margin/Scroll\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntheme_override_constants/separation = 10\n\n[node name=\"Speaker\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntheme_override_colors/font_color = Color(0.6, 0.85, 1, 1)\ntheme_override_font_sizes/font_size = 24\nautowrap_mode = 3\n\n[node name=\"Line\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\nautowrap_mode = 3\n\n[node name=\"Choices\" type=\"VBoxContainer\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntheme_override_constants/separation = 8\n\n[node name=\"Hint\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\nautowrap_mode = 3\n\n[node name=\"Close\" type=\"Button\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntext = \"Close conversation (Esc)\"\n\n[node name=\"VariablePanel\" type=\"PanelContainer\" parent=\".\"]\nvisible = false\nanchor_left = 1.0\nanchor_right = 1.0\noffset_left = -460.0\noffset_top = 86.0\noffset_right = -24.0\noffset_bottom = 300.0\ngrow_horizontal = 0\n\n[node name=\"Margin\" type=\"MarginContainer\" parent=\"VariablePanel\"]\nlayout_mode = 2\ntheme_override_constants/margin_left = 16\ntheme_override_constants/margin_top = 16\ntheme_override_constants/margin_right = 16\ntheme_override_constants/margin_bottom = 16\n\n[node name=\"Scroll\" type=\"ScrollContainer\" parent=\"VariablePanel/Margin\"]\nlayout_mode = 2\nhorizontal_scroll_mode = 0\n\n[node name=\"Rows\" type=\"VBoxContainer\" parent=\"VariablePanel/Margin/Scroll\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntheme_override_constants/separation = 8\n\n[node name=\"Explanation\" type=\"Label\" parent=\"VariablePanel/Margin/Scroll/Rows\"]\nlayout_mode = 2\ntext = \"Change variables to test conditional paths.\\nFights provide simulated win/loss choices.\"\nautowrap_mode = 3\n\n[node name=\"Close\" type=\"Button\" parent=\"VariablePanel/Margin/Scroll/Rows\"]\nlayout_mode = 2\ntext = \"Close test variables\"\n",
  "scenes/npc.tscn": "[gd_scene load_steps=3 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/npc.gd\" id=\"1\"]\n[sub_resource type=\"RectangleShape2D\" id=\"Shape\"]\nsize = Vector2(32, 32)\n\n[node name=\"NPC\" type=\"Area2D\"]\ncollision_layer = 0\ncollision_mask = 1\nscript = ExtResource(\"1\")\n\n[node name=\"Body\" type=\"Polygon2D\" parent=\".\"]\npolygon = PackedVector2Array(-16, -16, 16, -16, 16, 16, -16, 16)\n\n[node name=\"CollisionShape2D\" type=\"CollisionShape2D\" parent=\".\"]\nshape = SubResource(\"Shape\")\n\n[node name=\"NameLabel\" type=\"Label\" parent=\".\"]\noffset_left = -90.0\noffset_top = 24.0\noffset_right = 90.0\noffset_bottom = 86.0\nhorizontal_alignment = 1\nautowrap_mode = 3\n",
  "scenes/player.tscn": "[gd_scene load_steps=3 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/player.gd\" id=\"1\"]\n[sub_resource type=\"RectangleShape2D\" id=\"Shape\"]\nsize = Vector2(32, 32)\n\n[node name=\"Player\" type=\"CharacterBody2D\" groups=[\"player\"]]\ncollision_layer = 1\ncollision_mask = 2\nmotion_mode = 1\nscript = ExtResource(\"1\")\n\n[node name=\"Body\" type=\"Polygon2D\" parent=\".\"]\npolygon = PackedVector2Array(-16, -16, 16, -16, 16, 16, -16, 16)\ncolor = Color(0.35, 0.8, 1, 1)\n\n[node name=\"CollisionShape2D\" type=\"CollisionShape2D\" parent=\".\"]\nshape = SubResource(\"Shape\")\n\n[node name=\"NameLabel\" type=\"Label\" parent=\".\"]\noffset_left = -60.0\noffset_top = 22.0\noffset_right = 60.0\noffset_bottom = 50.0\ntext = \"YOU\"\nhorizontal_alignment = 1\n\n[node name=\"Camera2D\" type=\"Camera2D\" parent=\".\"]\nlimit_left = 0\nlimit_top = 0\nlimit_right = 960\nlimit_bottom = 640\n",
  "scripts/dialogue_session.gd": "extends RefCounted\r\n## Engine-independent traversal. Variables are shared with the playground.\r\n\r\nvar character: Dictionary\r\nvar variables: Dictionary\r\nvar nodes: Dictionary = {}\r\nvar current: Dictionary = {}\r\nvar waiting: Array = []\r\n\r\nfunc _init(data: Dictionary, game_variables: Dictionary) -> void:\r\n\tcharacter = data\r\n\tvariables = game_variables\r\n\tfor node in character.get(\"dialogueNodes\", []):\r\n\t\tnodes[str(int(node.dialogueID))] = node\r\n\r\nfunc go(id: Variant) -> Dictionary:\r\n\tcurrent = nodes.get(str(int(id)) if id != null else \"\", {})\r\n\twaiting = []\r\n\tfor line in current.get(\"outgoingLines\", []):\r\n\t\tfor condition in line.get(\"transitionConditions\", []):\r\n\t\t\tif condition.get(\"waitUntilMet\", true) and not allows(line):\r\n\t\t\t\twaiting.append(line)\r\n\t\t\t\tbreak\r\n\treturn current\r\n\r\nfunc allows(line: Dictionary) -> bool:\r\n\tfor condition in line.get(\"transitionConditions\", []):\r\n\t\tvar actual: Variant = variables.get(condition.variableName)\r\n\t\tvar expected: Variant = condition.variableValue\r\n\t\t# JSON numbers are floats. Compare numbers numerically, strings as strings.\r\n\t\tvar same_type := (actual is float or actual is int) and (expected is float or expected is int)\r\n\t\tsame_type = same_type or (actual is String and expected is String)\r\n\t\tvar passes := false\r\n\t\tmatch condition.comparisonOperator:\r\n\t\t\t\"=\": passes = same_type and actual == expected\r\n\t\t\t\"!=\": passes = not same_type or actual != expected\r\n\t\t\t\"<\": passes = same_type and actual < expected\r\n\t\t\t\">\": passes = same_type and actual > expected\r\n\t\t\t\"<=\": passes = same_type and actual <= expected\r\n\t\t\t\">=\": passes = same_type and actual >= expected\r\n\t\tif not passes:\r\n\t\t\treturn false\r\n\treturn true\r\n\r\nfunc start() -> Dictionary:\r\n\tif not current.is_empty() and not waiting.is_empty():\r\n\t\tif current.dialogueType not in [\"question\", \"fight\"]:\r\n\t\t\tfor line in waiting:\r\n\t\t\t\tif allows(line):\r\n\t\t\t\t\treturn go(line.toNode)\r\n\t\treturn current\r\n\tcurrent = {}\r\n\tfor line in character.get(\"outgoingLines\", []):\r\n\t\tif allows(line):\r\n\t\t\treturn go(line.toNode)\r\n\treturn current\r\n\r\nfunc can_advance(node: Dictionary) -> bool:\r\n\tvar lines: Array = node.get(\"outgoingLines\", [])\r\n\tif lines.is_empty():\r\n\t\treturn true\r\n\tfor line in lines:\r\n\t\tif allows(line):\r\n\t\t\treturn true\r\n\treturn false\r\n\r\nfunc advance(node: Dictionary) -> Dictionary:\r\n\tvar lines: Array = node.get(\"outgoingLines\", [])\r\n\tif lines.is_empty():\r\n\t\treturn go(node.get(\"nextNode\", -1))\r\n\tfor line in lines:\r\n\t\tif allows(line):\r\n\t\t\treturn go(line.toNode)\r\n\treturn current\r\n\r\nfunc options() -> Array:\r\n\tvar result: Array = []\r\n\tif current.is_empty():\r\n\t\treturn result\r\n\tvar lines: Array = current.get(\"outgoingLines\", [])\r\n\tmatch current.dialogueType:\r\n\t\t\"question\":\r\n\t\t\tfor line in lines:\r\n\t\t\t\tvar answer: Dictionary = nodes.get(str(int(line.toNode)), {})\r\n\t\t\t\tresult.append({\"text\": answer.get(\"dialogueText\", \"(Empty answer)\"),\r\n\t\t\t\t\t\"enabled\": allows(line) and can_advance(answer), \"node\": answer})\r\n\t\t\"fight\":\r\n\t\t\tfor index in range(lines.size()):\r\n\t\t\t\tvar label := \"Win the fight\" if index == 0 else \"Lose the fight\"\r\n\t\t\t\tif index > 1:\r\n\t\t\t\t\tlabel = \"Outcome %d\" % (index + 1)\r\n\t\t\t\tresult.append({\"text\": label, \"enabled\": allows(lines[index]), \"target\": lines[index].toNode})\r\n\t\t_:\r\n\t\t\tvar label := \"Continue\" if not lines.is_empty() or int(current.get(\"nextNode\", -1)) > 0 else \"Finish\"\r\n\t\t\tresult.append({\"text\": label, \"enabled\": can_advance(current), \"node\": current})\r\n\treturn result\r\n\r\nfunc choose(index: int) -> Dictionary:\r\n\tvar choices := options()\r\n\tif index < 0 or index >= choices.size() or not choices[index].enabled:\r\n\t\treturn current\r\n\tvar choice: Dictionary = choices[index]\r\n\tif choice.has(\"target\"):\r\n\t\treturn go(choice.target)\r\n\treturn advance(choice.node)\r\n",
  "scripts/dialogue_ui.gd": "extends CanvasLayer\r\n## Native Godot controls; no web view or external dependencies.\r\n\r\nsignal busy_changed(locked: bool)\r\nconst Session = preload(\"res://scripts/dialogue_session.gd\")\r\nvar characters: Array = []\r\nvar variables: Dictionary = {}\r\nvar sessions: Dictionary = {}\r\nvar session: RefCounted\r\nvar page: int = 0\r\n@onready var panel: PanelContainer = $DialoguePanel\r\n@onready var content: VBoxContainer = $DialoguePanel/Margin/Scroll/Content\r\n@onready var variable_panel: PanelContainer = $VariablePanel\r\n@onready var variable_rows: VBoxContainer = $VariablePanel/Margin/Scroll/Rows\r\n\r\nfunc _ready() -> void:\r\n\tcontent.get_node(\"Close\").pressed.connect(close_dialogue)\r\n\t$HUD/Row/Variables.pressed.connect(_toggle_variables)\r\n\tvariable_rows.get_node(\"Close\").pressed.connect(_toggle_variables)\r\n\r\nfunc configure(data: Array) -> void:\r\n\tcharacters = data\r\n\tsessions.clear()\r\n\tfor character in characters:\r\n\t\tif not character.has(\"dialogueNodes\"): character.dialogueNodes = []\r\n\t\tif not character.has(\"outgoingLines\"): character.outgoingLines = []\r\n\t\tfor node in character.dialogueNodes:\r\n\t\t\tif not node.has(\"outgoingLines\"): node.outgoingLines = []\r\n\tfor character in characters:\r\n\t\tvar sources: Array = [character] + character.get(\"dialogueNodes\", [])\r\n\t\tfor source in sources:\r\n\t\t\tfor line in source.get(\"outgoingLines\", []):\r\n\t\t\t\tfor condition in line.get(\"transitionConditions\", []):\r\n\t\t\t\t\tif not variables.has(condition.variableName):\r\n\t\t\t\t\t\tvariables[condition.variableName] = 0.0 if condition.variableValue is float or condition.variableValue is int else \"\"\r\n\tfor key in variables:\r\n\t\tvar row := HBoxContainer.new()\r\n\t\trow.set_meta(\"variable_name\", key)\r\n\t\tvar label := Label.new()\r\n\t\tlabel.text = key\r\n\t\tlabel.size_flags_horizontal = Control.SIZE_EXPAND_FILL\r\n\t\trow.add_child(label)\r\n\t\tif variables[key] is float or variables[key] is int:\r\n\t\t\tvar input := SpinBox.new()\r\n\t\t\tinput.allow_greater = true\r\n\t\t\tinput.allow_lesser = true\r\n\t\t\tinput.step = 0.01\r\n\t\t\tinput.custom_minimum_size.x = 150\r\n\t\t\tinput.value_changed.connect(func(value: float): _set_variable(key, value))\r\n\t\t\trow.add_child(input)\r\n\t\telse:\r\n\t\t\tvar input := LineEdit.new()\r\n\t\t\tinput.custom_minimum_size.x = 150\r\n\t\t\tinput.text_changed.connect(func(value: String): _set_variable(key, value))\r\n\t\t\trow.add_child(input)\r\n\t\tvariable_rows.add_child(row)\r\n\r\nfunc _set_variable(key: String, value: Variant) -> void:\r\n\tvariables[key] = value\r\n\tif session != null:\r\n\t\t_render(false)\r\n\r\nfunc set_game_variable(key: String, value: Variant) -> void:\r\n\t_set_variable(key, value)\r\n\tfor row in variable_rows.get_children():\r\n\t\tif row.get_meta(\"variable_name\", \"\") == key:\r\n\t\t\tvar input = row.get_child(1)\r\n\t\t\tif input is SpinBox:\r\n\t\t\t\tinput.set_value_no_signal(float(value))\r\n\t\t\telif input is LineEdit:\r\n\t\t\t\tinput.text = str(value)\r\n\r\nfunc is_busy() -> bool:\r\n\treturn panel.visible or variable_panel.visible\r\n\r\nfunc _toggle_variables() -> void:\r\n\tvariable_panel.visible = not variable_panel.visible\r\n\tbusy_changed.emit(is_busy())\r\n\r\nfunc open_character_id(character_id: String) -> void:\r\n\tfor index in range(characters.size()):\r\n\t\tif str(int(characters[index].get(\"characterID\", -1))) == character_id:\r\n\t\t\topen_character(index)\r\n\t\t\treturn\r\n\r\nfunc open_character(index: int) -> void:\r\n\tif is_busy() or index < 0 or index >= characters.size():\r\n\t\treturn\r\n\tif not sessions.has(index):\r\n\t\tsessions[index] = Session.new(characters[index], variables)\r\n\tsession = sessions[index]\r\n\tsession.start()\r\n\tpage = 0\r\n\tpanel.show()\r\n\tbusy_changed.emit(true)\r\n\t_render()\r\n\r\nfunc close_dialogue() -> void:\r\n\tpanel.hide()\r\n\tsession = null\r\n\tbusy_changed.emit(is_busy())\r\n\r\nfunc _input(event: InputEvent) -> void:\r\n\tif event.is_action_pressed(\"ui_cancel\") and is_busy():\r\n\t\tvariable_panel.hide()\r\n\t\tclose_dialogue()\r\n\t\tget_viewport().set_input_as_handled()\r\n\tif not event is InputEventKey or not event.pressed or event.echo or session == null or variable_panel.visible:\r\n\t\treturn\r\n\tif event.ctrl_pressed or event.alt_pressed or event.meta_pressed or event.shift_pressed:\r\n\t\treturn\r\n\tif [\"move_left\", \"move_right\", \"move_up\", \"move_down\"].any(func(action): return event.is_action_pressed(action)):\r\n\t\tclose_dialogue()\r\n\t\treturn\r\n\tvar code: int = event.physical_keycode if event.physical_keycode else event.keycode\r\n\tvar index: int = code - KEY_1 if code >= KEY_1 and code <= KEY_9 else code - KEY_KP_1 if code >= KEY_KP_1 and code <= KEY_KP_9 else -1\r\n\tvar choices := content.get_node(\"Choices\").get_children()\r\n\tif index >= 0 and index < choices.size():\r\n\t\tget_viewport().set_input_as_handled()\r\n\t\tif not choices[index].disabled:\r\n\t\t\tchoices[index].pressed.emit()\r\n\r\nfunc _render(focus_choice: bool = true) -> void:\r\n\tif session == null:\r\n\t\treturn\r\n\tcontent.get_node(\"Speaker\").text = str(session.character.get(\"characterName\", \"Unnamed character\"))\r\n\tvar choices: VBoxContainer = content.get_node(\"Choices\")\r\n\tfor child in choices.get_children():\r\n\t\tchoices.remove_child(child)\r\n\t\tchild.queue_free()\r\n\tvar answer_speaker := content.get_node_or_null(\"AnswerSpeaker\")\r\n\tif answer_speaker == null:\r\n\t\tanswer_speaker = Label.new()\r\n\t\tanswer_speaker.name = \"AnswerSpeaker\"\r\n\t\tanswer_speaker.text = \"You\"\r\n\t\tanswer_speaker.modulate = Color(0.61, 0.85, 1)\r\n\t\tcontent.add_child(answer_speaker)\r\n\t\tcontent.move_child(answer_speaker, choices.get_index())\r\n\tanswer_speaker.hide()\r\n\tcontent.get_node(\"Hint\").text = \"\"\r\n\tif session.current.is_empty():\r\n\t\tcontent.get_node(\"Line\").text = \"No available starting dialogue. Check the root connection or test variables.\"\r\n\t\t_add_button(\"Try again\", func(): session.start(); page = 0; _render())\r\n\telse:\r\n\t\tvar pages := str(session.current.get(\"dialogueText\", \"\")).replace(\"\\r\\n\", \"\\n\").split(\"\\n\")\r\n\t\tvar speakers: Array = session.current.get(\"dialogueSpeakers\", [])\r\n\t\tvar role: String = str(speakers[page]) if page < speakers.size() else \"player\" if session.current.get(\"dialogueType\") == \"answer\" else \"npc\"\r\n\t\tcontent.get_node(\"Speaker\").text = \"You\" if role == \"player\" else \"Scene\" if role == \"scene\" else str(session.character.get(\"characterName\", \"Unnamed character\"))\r\n\t\tcontent.get_node(\"Line\").text = pages[page]\r\n\t\tif page < pages.size() - 1:\r\n\t\t\t_add_button(\"Continue\", func(): page += 1; _render())\r\n\t\telse:\r\n\t\t\tanswer_speaker.visible = session.current.get(\"dialogueType\") == \"question\"\r\n\t\t\tvar options: Array = session.options()\r\n\t\t\tfor index in range(options.size()):\r\n\t\t\t\tvar option: Dictionary = options[index]\r\n\t\t\t\t_add_button(str(option.text), _choose.bind(index), option.enabled)\r\n\t\t\t\tif not option.enabled:\r\n\t\t\t\t\tcontent.get_node(\"Hint\").text = \"Some paths are locked. Use Test variables to try them.\"\r\n\t$DialoguePanel/Margin/Scroll.scroll_vertical = 0\r\n\tif focus_choice:\r\n\t\tfor child in choices.get_children():\r\n\t\t\tif not child.disabled:\r\n\t\t\t\tchild.grab_focus()\r\n\t\t\t\tbreak\r\n\r\nfunc _add_button(text: String, action: Callable, enabled: bool = true) -> void:\r\n\tvar button := Button.new()\r\n\tbutton.text = text\r\n\tbutton.alignment = HORIZONTAL_ALIGNMENT_LEFT\r\n\t# Keep the theme background while reserving a separate number gutter.\r\n\tfor state in [\"normal\", \"hover\", \"pressed\", \"focus\", \"disabled\"]:\r\n\t\tvar box := button.get_theme_stylebox(state).duplicate() as StyleBox\r\n\t\tbox.content_margin_left = 36\r\n\t\tbox.content_margin_right = 10\r\n\t\tbutton.add_theme_stylebox_override(state, box)\r\n\tvar number := Label.new()\r\n\tnumber.text = str(content.get_node(\"Choices\").get_child_count() + 1)\r\n\tnumber.position = Vector2(12, 10)\r\n\tnumber.modulate.a = 0.45\r\n\tnumber.add_theme_font_size_override(\"font_size\", 12)\r\n\tnumber.mouse_filter = Control.MOUSE_FILTER_IGNORE\r\n\tbutton.add_child(number)\r\n\tbutton.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART\r\n\tbutton.custom_minimum_size.y = 40\r\n\tbutton.disabled = not enabled\r\n\tbutton.pressed.connect(action)\r\n\tcontent.get_node(\"Choices\").add_child(button)\r\n\r\nfunc _choose(index: int) -> void:\r\n\tsession.choose(index)\r\n\tpage = 0\r\n\tif session.current.is_empty():\r\n\t\tclose_dialogue()\r\n\telse:\r\n\t\t_render()\r\n\r\nfunc show_error(message: String) -> void:\r\n\tpanel.show()\r\n\tcontent.get_node(\"Speaker\").text = \"Dialogue error\"\r\n\tcontent.get_node(\"Line\").text = message\r\n",
  "scripts/main.gd": "extends Node2D\r\n\r\nvar apple: Area2D\r\n\r\nfunc _ready() -> void:\r\n\tvar text := FileAccess.get_file_as_string(\"res://dialogue.json\")\r\n\tvar data: Variant = JSON.parse_string(text)\r\n\tif not data is Dictionary or not data.get(\"characters\") is Array:\r\n\t\t$DialogueUI.show_error(\"Could not load dialogue.json. Check its JSON syntax.\")\r\n\t\t$Player.movement_locked = true\r\n\t\treturn\r\n\t$DialogueUI.configure(data.characters)\r\n\t$DialogueUI.busy_changed.connect(_on_busy_changed)\r\n\tfor npc in $NPCs.get_children():\r\n\t\tif not npc.character_id.is_empty():\r\n\t\t\tnpc.character_index = -1\r\n\t\t\tfor index in range(data.characters.size()):\r\n\t\t\t\tif str(int(data.characters[index].get(\"characterID\", -1))) == npc.character_id:\r\n\t\t\t\t\tnpc.character_index = index\r\n\t\t\t\t\tbreak\r\n\t\tif npc.character_index < 0 or npc.character_index >= data.characters.size():\r\n\t\t\tcontinue\r\n\t\tnpc.set_character_name(str(data.characters[npc.character_index].get(\"characterName\", \"Unnamed character\")))\r\n\t\tnpc.talk_requested.connect($DialogueUI.open_character)\r\n\t$Player/Camera2D.limit_bottom = int($Player.world_size.y)\r\n\tif data.get(\"demoAppleQuest\", false):\r\n\t\tapple = Area2D.new()\r\n\t\tapple.name = \"Apple\"\r\n\t\tapple.position = Vector2(580, 180)\r\n\t\tapple.collision_layer = 0\r\n\t\tapple.collision_mask = 1\r\n\t\tvar sprite := Sprite2D.new()\r\n\t\tsprite.texture = load(\"res://art/apple.png\")\r\n\t\tapple.add_child(sprite)\r\n\t\tvar collision := CollisionShape2D.new()\r\n\t\tvar shape := RectangleShape2D.new()\r\n\t\tshape.size = Vector2(28, 28)\r\n\t\tcollision.shape = shape\r\n\t\tapple.add_child(collision)\r\n\t\tapple.body_entered.connect(_pick_up_apple)\r\n\t\tadd_child(apple)\r\n\t\t$DialogueUI/HUD/Row/Instructions.text += \"\\nApple: not collected. Talk to Mira.\"\r\n\r\nfunc _pick_up_apple(body: Node2D) -> void:\r\n\tif body != $Player or not is_instance_valid(apple) or $DialogueUI.is_busy():\r\n\t\treturn\r\n\t$DialogueUI.set_game_variable(\"hasApple\", 1.0)\r\n\tapple.queue_free()\r\n\tapple = null\r\n\t$DialogueUI/HUD/Row/Instructions.text = \"Move: arrows / WASD. Apple collected! Return to Mira.\"\r\n\r\nfunc _on_busy_changed(locked: bool) -> void:\r\n\t$Player.movement_locked = locked\r\n",
  "scripts/npc.gd": "extends Area2D\r\n\r\nsignal talk_requested(character_index: int)\r\n@export var character_index: int = 0\r\n@export var character_id: String = \"\"\r\n@export var tint := Color(\"b68af7\")\r\n\r\nfunc _ready() -> void:\r\n\t$Body.color = tint\r\n\tbody_entered.connect(_on_body_entered)\r\n\r\nfunc _on_body_entered(body: Node2D) -> void:\r\n\tif body.is_in_group(\"player\"):\r\n\t\ttalk_requested.emit(character_index)\r\n\r\nfunc set_character_name(value: String) -> void:\r\n\t$NameLabel.text = value\r\n",
  "scripts/player.gd": "extends CharacterBody2D\n\n@export var speed: float = 220.0\n@export var world_size := Vector2(960, 640)\nvar movement_locked: bool = false\n\nfunc _physics_process(_delta: float) -> void:\n\tif movement_locked:\n\t\tvelocity = Vector2.ZERO\n\t\treturn\n\tvelocity = Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\") * speed\n\tmove_and_slide()\n\tposition = position.clamp(Vector2(20, 100), world_size - Vector2(20, 20))\n"
};
if (typeof module !== "undefined") module.exports = godotTemplate;
